      id: 'singapore-buddha-tooth-relic-temple', city: 'singapore', category: 'attraction', lat: 1.2811, lng: 103.8445, image: 's3i02B7qiVA', // TODO(photo): reuse a Singapore photo; swap for the temple
      rating: 4.6, reviews: 16700, tags: ['temples', 'culture', 'architecture'], price: { kind: 'free' }, hours: '07:00–17:00',
      address: '288 South Bridge Road, Singapore 058840',
      text: {
        ru: { name: 'Храм Зуба Будды', description: 'Пятиэтажный храм в стиле династии Тан в Чайнатауне, где хранится реликвия — зуб Будды. На крыше — сад с огромным молитвенным колесом.', tip: 'Заходите утром и в длинной одежде: плечи и колени закрывают. Фотографировать можно во дворе и на крыше, но не в зале с реликвией; вход бесплатный, музей внутри тоже.' },
        en: { name: 'Buddha Tooth Relic Temple', description: 'A five-storey Tang-style temple in Chinatown that houses a relic, a tooth of the Buddha. A rooftop garden holds a giant prayer wheel.', tip: 'Visit in the morning, dressed with covered shoulders and knees. Photography is fine in the courtyard and on the roof, but not in the relic hall; entry and the museum inside are free.' },
        es: { name: 'Templo de la Reliquia del Diente de Buda', description: 'Un templo de cinco plantas de estilo Tang en Chinatown que guarda una reliquia, un diente de Buda. En la azotea hay un jardín con una rueda de oración gigante.', tip: 'Visítalo por la mañana, con hombros y rodillas cubiertos. Se puede fotografiar en el patio y en la azotea, pero no en la sala de la reliquia; la entrada y el museo interior son gratuitos.' },
        de: { name: 'Buddha-Zahn-Reliquientempel', description: 'Ein fünfstöckiger Tempel im Tang-Stil in Chinatown, in dem eine Reliquie, ein Zahn des Buddha, aufbewahrt wird. Auf dem Dach liegt ein Garten mit einem riesigen Gebetsrad.', tip: 'Besuche ihn vormittags mit bedeckten Schultern und Knien. Fotografieren ist im Hof und auf dem Dach erlaubt, aber nicht in der Reliquienhalle; Eintritt und Museum sind frei.' },
        fr: { name: 'Temple de la Relique de la Dent de Bouddha', description: 'Un temple de cinq étages de style Tang à Chinatown qui abrite une relique, une dent du Bouddha. Un jardin sur le toit renferme un moulin à prières géant.', tip: 'Visitez-le le matin, épaules et genoux couverts. La photo est permise dans la cour et sur le toit, mais pas dans la salle de la relique ; l’entrée et le musée intérieur sont gratuits.' },
        it: { name: 'Tempio della Reliquia del Dente di Buddha', description: 'Un tempio di cinque piani in stile Tang a Chinatown che custodisce una reliquia, un dente del Buddha. Sul tetto c’è un giardino con una gigantesca ruota di preghiera.', tip: 'Visitalo al mattino, con spalle e ginocchia coperte. Si può fotografare nel cortile e sul tetto, ma non nella sala della reliquia; l’ingresso e il museo interno sono gratuiti.' },
      },
